#!/usr/bin/env node
// Corpus builder: generates experiments/corpus.mjs from the source of truth.
//
// Source of truth:
//   experiments/tasks/*.txt    one plain sentence per task (the agent prompt)
//   experiments/tasks/*.yaml   the contract envelope
//   experiments/seeded.json    handwritten seeded defects, keyed by RF id,
//                              copied into the generated file verbatim
//
// experiments/corpus.mjs is a GENERATED artifact. Edit the files above, then
// run `npm run build:corpus`. test/corpus-sync.test.mjs fails while stale.
import { readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { parse } from "yaml";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
export const CORPUS_FILE = join(ROOT, "experiments", "corpus.mjs");

const HEADER = [
  "// GENERATED by `npm run build:corpus` - do not edit by hand.",
  "// Source of truth: experiments/tasks/*.txt, experiments/tasks/*.yaml,",
  "// experiments/seeded.json. Seeded defects are copied here verbatim.",
  "",
].join("\n");

export async function readCorpusInputs() {
  const tasksDir = join(ROOT, "experiments", "tasks");
  const seeded = JSON.parse(await readFile(join(ROOT, "experiments", "seeded.json"), "utf8"));
  const names = (await readdir(tasksDir)).filter((name) => /^RF-\d+\.yaml$/.test(name)).sort();
  const entries = [];
  for (const name of names) {
    const id = name.replace(/\.yaml$/, "");
    const contract = parse(await readFile(join(tasksDir, name), "utf8"));
    const sentence = (await readFile(join(tasksDir, `${id}.txt`), "utf8")).trim();
    entries.push({ id, sentence, contract });
  }
  entries.sort((a, b) => a.id.localeCompare(b.id));
  return { entries, seeded };
}

function indentBlock(text, spaces) {
  const pad = " ".repeat(spaces);
  return text
    .split("\n")
    .map((line, index) => (index === 0 ? line : pad + line))
    .join("\n");
}

function assertSeeded(entries, seeded) {
  const missing = entries.filter((entry) => typeof seeded[entry.id] !== "string" || !seeded[entry.id].trim());
  const orphans = Object.keys(seeded).filter((id) => !entries.some((entry) => entry.id === id));
  if (missing.length) {
    throw new Error(`experiments/seeded.json has no seeded defect for: ${missing.map((e) => e.id).join(", ")}`);
  }
  if (orphans.length) {
    throw new Error(`experiments/seeded.json has entries with no matching task file: ${orphans.join(", ")}`);
  }
}

// Pure: deterministic source string from parsed inputs (stable ordering by RF id).
export function buildCorpusSource({ entries, seeded }) {
  const sorted = [...entries].sort((a, b) => a.id.localeCompare(b.id));
  assertSeeded(sorted, seeded);

  const seededLines = sorted.map((entry) => `  ${JSON.stringify(entry.id)}: ${seeded[entry.id]},`);
  const taskLines = sorted.map((entry) => {
    const lines = [
      "  {",
      `    sentence: ${JSON.stringify(entry.sentence)},`,
      `    seeded: seeded[${JSON.stringify(entry.id)}],`,
      `    contract: ${indentBlock(JSON.stringify(entry.contract, null, 2), 4)},`,
      "  },",
    ];
    return lines.join("\n");
  });

  return [
    HEADER,
    "const seeded = {",
    ...seededLines,
    "};",
    "",
    "export const tasks = [",
    ...taskLines,
    "];",
    "",
  ].join("\n");
}

export async function generateCorpusSource() {
  return buildCorpusSource(await readCorpusInputs());
}

export async function corpusSyncStatus() {
  try {
    const generated = await generateCorpusSource();
    let onDisk = null;
    try {
      onDisk = await readFile(CORPUS_FILE, "utf8");
    } catch {
      onDisk = null;
    }
    const synced = onDisk === generated;
    return {
      synced,
      message: synced ? "corpus in sync" : "corpus is stale - run npm run build:corpus",
      fix: synced ? null : "npm run build:corpus",
    };
  } catch (error) {
    return { synced: false, message: error.message, fix: "npm run build:corpus" };
  }
}

async function main() {
  const source = await generateCorpusSource();
  const current = await readFile(CORPUS_FILE, "utf8").catch(() => null);
  if (current === source) {
    process.stdout.write("experiments/corpus.mjs is up to date\n");
    return;
  }
  await writeFile(CORPUS_FILE, source);
  process.stdout.write("wrote experiments/corpus.mjs\n");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    process.stderr.write(`${error.message}\n`);
    process.exit(1);
  });
}
